export async function loadRawExercisesForLegacyId(legacyLessonId?: string): Promise<Exercise[]> {
  if (!legacyLessonId) return [];
  const chapterKey = chapterByLegacyLessonId[legacyLessonId];
  const loadChapter = chapterKey ? chapterLoaders[chapterKey] : undefined;
  if (!loadChapter) return [];
  return (await loadChapter())[legacyLessonId] ?? [];
}
